/**
 * Q&A Page Logic for KhmerResearch.com
 * Displays pre-generated Q&A from articles + community questions.
 * Depends on firebase-init.js being loaded first.
 */
(function () {
  "use strict";

  var allQA = [];
  var filteredQA = [];
  var activeCategory = null;

  function init() {
    loadGeneratedQA();
    loadCommunityQuestions();
    setupSearch();
    setupAskForm();
  }

  function loadGeneratedQA() {
    var container = document.getElementById("qa-generated-list");
    if (!container) return;

    // Load from the embedded JSON data (generated by Python script)
    var dataEl = document.getElementById("qa-data");
    if (dataEl) {
      try {
        // The embedded JSON contains literal newlines inside string values
        // (used to separate EN/KM paragraphs). Escape them for JSON.parse.
        var raw = (dataEl.textContent || "[]").replace(/\r?\n/g, "\\n");
        allQA = JSON.parse(raw);
      } catch (e) {
        console.warn("Failed to parse qa-data JSON:", e);
        allQA = [];
      }
    }

    filteredQA = allQA.slice();
    renderCategoryPills();
    renderQAList();
  }

  /**
   * Split bilingual text: English paragraph + Khmer paragraph separated by \n\n
   * Returns { en: string, km: string }
   */
  function splitBilingual(text) {
    if (!text) return { en: '', km: '' };
    // Khmer Unicode range: \u1780-\u17FF
    var parts = text.split(/\n\n/);
    if (parts.length >= 2) {
      // Find first part that contains Khmer characters (may start with Latin brand name)
      for (var i = 1; i < parts.length; i++) {
        var trimmed = parts[i].trim();
        if (/[\u1780-\u17FF]/.test(trimmed)) {
          return { en: parts.slice(0, i).join('\n\n').trim(), km: parts.slice(i).join('\n\n').trim() };
        }
      }
    }
    return { en: text.trim(), km: '' };
  }

  /**
   * Split bilingual question: "English question (Khmer question)"
   * Returns { en: string, km: string }
   */
  function splitQuestion(text) {
    if (!text) return { en: '', km: '' };
    // Match pattern: English text (Khmer text)
    var m = text.match(/^(.*?)\s*\(([\u1780-\u17FF].*)\)\s*$/);
    if (m) {
      return { en: m[1].trim(), km: m[2].trim() };
    }
    return { en: text.trim(), km: '' };
  }

  function renderCategoryPills() {
    var container = document.getElementById("qa-category-pills");
    if (!container) return;

    // Collect unique categories
    var cats = {};
    for (var i = 0; i < allQA.length; i++) {
      var c = allQA[i].category;
      if (c) cats[c] = (cats[c] || 0) + 1;
    }

    var html = '<button class="kr-pill active" data-cat="">All</button>';
    var keys = Object.keys(cats);
    for (var j = 0; j < keys.length; j++) {
      html += '<button class="kr-pill" data-cat="' + window.KR.escapeHtml(keys[j]) + '">' + window.KR.escapeHtml(keys[j]) + ' <span class="kr-pill-count">' + cats[keys[j]] + '</span></button>';
    }
    container.innerHTML = html;

    // Attach click handlers
    var pills = container.querySelectorAll(".kr-pill");
    pills.forEach(function (pill) {
      pill.addEventListener("click", function () {
        pills.forEach(function (p) { p.classList.remove("active"); });
        pill.classList.add("active");
        activeCategory = pill.getAttribute("data-cat") || null;
        applyFilters();
      });
    });
  }

  function renderQAList() {
    var container = document.getElementById("qa-generated-list");
    if (!container) return;

    if (filteredQA.length === 0) {
      container.innerHTML = '<div class="kr-empty">No matching questions found. មិនមានសំណួរដែលត្រូវគ្នាទេ។</div>';
      return;
    }

    var html = '';
    for (var i = 0; i < filteredQA.length; i++) {
      var qa = filteredQA[i];
      var q = splitQuestion(qa.question);
      var a = splitBilingual(qa.answer);

      html +=
        '<div class="kr-qa-item" data-index="' + i + '">' +
          '<div class="kr-qa-question">' +
            '<div class="kr-qa-question-text">' +
              '<p class="kr-qa-q-en">' + window.KR.escapeHtml(q.en) + '</p>' +
              (q.km ? '<p class="kr-qa-q-km khmer-text">' + window.KR.escapeHtml(q.km) + '</p>' : '') +
            '</div>' +
            '<span class="kr-qa-toggle">' +
              '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>' +
            '</span>' +
          '</div>' +
          '<div class="kr-qa-answer">' +
            '<div class="kr-qa-answer-en">' +
              '<p>' + window.KR.escapeHtml(a.en) + '</p>' +
            '</div>' +
            (a.km ? '<div class="kr-qa-answer-km khmer-text"><p>' + window.KR.escapeHtml(a.km) + '</p></div>' : '') +
            (qa.source ? '<div class="kr-qa-answer-source">Source: <a href="' + window.KR.escapeHtml(qa.url || "#") + '">' + window.KR.escapeHtml(qa.source) + '</a></div>' : '') +
            (qa.category ? '<span class="kr-thread-category" style="margin-top:8px;display:inline-block">' + window.KR.escapeHtml(qa.category) + '</span>' : '') +
          '</div>' +
        '</div>';
    }
    container.innerHTML = html;

    // Re-attach accordion handlers
    setupAccordion();
  }

  function applyFilters() {
    var input = document.getElementById("qa-search-input");
    var query = input ? input.value.trim().toLowerCase() : '';

    filteredQA = allQA.filter(function (qa) {
      // Category filter
      if (activeCategory && qa.category !== activeCategory) return false;
      // Text search
      if (query) {
        return (
          (qa.question || "").toLowerCase().indexOf(query) !== -1 ||
          (qa.answer || "").toLowerCase().indexOf(query) !== -1 ||
          (qa.category || "").toLowerCase().indexOf(query) !== -1
        );
      }
      return true;
    });
    renderQAList();
  }

  function setupSearch() {
    var input = document.getElementById("qa-search-input");
    if (!input) return;

    var debounceTimer;
    input.addEventListener("input", function () {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(applyFilters, 300);
    });
  }

  function setupAccordion() {
    var container = document.getElementById("qa-generated-list");
    if (!container || container._accordionBound) return;
    container._accordionBound = true;

    // Use event delegation — single listener on the container
    container.addEventListener("click", function (e) {
      var question = e.target.closest(".kr-qa-question");
      if (!question) return;
      var item = question.closest(".kr-qa-item");
      if (!item) return;

      var wasOpen = item.classList.contains("open");
      // Close all others
      document.querySelectorAll(".kr-qa-item.open").forEach(function (el) {
        el.classList.remove("open");
      });
      if (!wasOpen) {
        item.classList.add("open");
      }
    });
  }

  function loadCommunityQuestions() {
    var container = document.getElementById("qa-community-list");
    if (!container) return;

    window.KR.onReady(function () {
      var questionsRef = window.KR.dbRef("qa/community");
      questionsRef.orderByChild("createdAt").limitToLast(50).on("value", function (snap) {
        var questions = [];
        snap.forEach(function (child) {
          var q = child.val();
          q._key = child.key;
          questions.push(q);
        });
        questions.reverse();

        if (questions.length === 0) {
          container.innerHTML = '<div class="kr-empty">No community questions yet. Ask the first one!</div>';
          return;
        }

        var html = "";
        for (var i = 0; i < questions.length; i++) {
          var q = questions[i];
          html +=
            '<div class="kr-community-q">' +
              '<div class="kr-community-q-header">' +
                '<strong>' + window.KR.escapeHtml(q.authorName || "Anonymous") + '</strong>' +
                '<span class="kr-community-q-time">' + window.KR.formatTime(q.createdAt) + '</span>' +
              '</div>' +
              '<p class="kr-community-q-text">' + window.KR.escapeHtml(q.question || "") + '</p>' +
            '</div>';
        }
        container.innerHTML = html;
      });
    });
  }

  function setupAskForm() {
    var section = document.getElementById("qa-ask-section");
    if (!section) return;

    function renderForm(user) {
      if (!user) {
        section.innerHTML =
          '<div class="kr-new-thread">' +
            '<h3>Ask a Question</h3>' +
            '<p style="color:var(--kr-text-secondary);font-size:14px;margin-bottom:12px">Sign in to ask a question:</p>' +
            '<div class="kr-auth-actions">' +
              '<button class="kr-btn kr-btn-google" onclick="KR.signInWithGoogle()">Sign in with Google</button>' +
              '<button class="kr-btn kr-btn-anon" onclick="KR.signInAnonymously()">Ask Anonymously</button>' +
            '</div>' +
          '</div>';
        return;
      }

      var name = user.isAnonymous ? "Anonymous" : (user.displayName || user.email || "User");
      section.innerHTML =
        '<div class="kr-new-thread">' +
          '<h3>Ask a Question</h3>' +
          '<p style="color:var(--kr-text-muted);font-size:13px;margin-bottom:12px">Asking as: ' + window.KR.escapeHtml(name) + '</p>' +
          '<div class="kr-form-group">' +
            '<textarea id="qa-question-text" placeholder="What would you like to know about Cambodian research?" rows="3" maxlength="1000"></textarea>' +
          '</div>' +
          '<div class="kr-form-actions">' +
            '<button class="kr-btn kr-btn-primary" id="qa-submit-btn">Submit Question</button>' +
          '</div>' +
        '</div>';

      document.getElementById("qa-submit-btn").onclick = submitQuestion;
    }

    document.addEventListener("kr-auth-changed", function (e) {
      renderForm(e.detail.user);
    });

    // Render immediately if known
    window.KR.onReady(function () {
      renderForm(window.KR.currentUser);
    });
  }

  function submitQuestion() {
    var user = window.KR.currentUser;
    if (!user) return;

    var textarea = document.getElementById("qa-question-text");
    var text = (textarea.value || "").trim();
    if (!text) { alert("Please enter a question."); return; }
    if (text.length > 1000) { alert("Question is too long (max 1000 characters)."); return; }

    var questionData = {
      question: text,
      authorName: user.isAnonymous ? "Anonymous" : (user.displayName || user.email || "User"),
      authorUid: user.uid,
      isAnonymous: user.isAnonymous || false,
      createdAt: firebase.database.ServerValue.TIMESTAMP
    };

    var questionsRef = window.KR.dbRef("qa/community");
    questionsRef.push(questionData).then(function () {
      textarea.value = "";
    }).catch(function (err) {
      console.error("Failed to submit question:", err);
      alert("Failed to submit question. Please try again.");
    });
  }

  // Run when DOM ready
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
